\[ \begin{aligned} u = \{u_1,u_2,\ldots,u_n\} \\ v = \{v_1,v_2,\ldots,v_n\} \\ u.v = \{u_1*v_1 + u_2*v_2+\ldots+u_n*v_n\} \end{aligned} \] <p>Ejemplo</p> \[ \begin{aligned} v = \{1,2,3\} \\  u = \{4,5,6\} \\ u.v = 4 + 10 + 18 = 32 \end{aligned} \] <p>Hasta el momento para reconocer patrones de listas paralelas es necesario identificar el caso de la primera y luego evaluar el de la segunda, esto hace que el código no sea facil de mantener o entender.</p> <p></p><pre><code>import scala.annotation.tailrec
object ProductoPunto {

  def prod(u:List[Int])(v:List[Int]):Int = {
    @tailrec
    def prodI(u:List[Int])(v:List[Int])(acc:Int):Int = {
      u match {
        case Nil =&gt; v match {
          case Nil =&gt; acc  // Ambas listas vacías, retorna acumulador
          case _ =&gt; throw new Exception("Las listas deben ser el mismo tamaño")
        }
          case x :: xs =&gt; v match {
            case Nil =&gt; throw new Exception("La listas deben ser el mismo tamaño") 
            case y :: ys =&gt; prodI(xs)(ys)(x*y + acc) // Multiplica elementos y suma al acumulador
          }
      }
    }
    prodI(u)(v)(0) // Llama a la función interna con acumulador inicial 0

  }

  def main(arr:Array[String]):Unit = {
    val u = List(1,2,3)
    val v = List(4,5,6)
    println(prod(u)(v)) // Calcula producto punto: 1*4 + 2*5 + 3*6 = 32
  }

}
</code></pre> Ahora podemos usar tuplas para reconocer patrones de más de una variable al mismo tiempo, evitando anidamientos <pre><code>import scala.annotation.tailrec
